task.vi:
Viết chương trình chuyển đổi nhiệt độ Fahrenheit nguyên từ 0 đến 212 độ sang nhiệt độ Celsius dấu phẩy động với 3 chữ số độ chính xác. Sử dụng công thức:
celsius = 5.0 / 9.0 * ( fahrenheit - 32 );
để thực hiện tính toán. Đầu ra phải được in thành hai cột căn lề phải và nhiệt độ Celsius phải có dấu đứng trước cho cả giá trị dương và âm.

task.en:
Write a program that converts integer Fahrenheit temperatures from 0 to 212 degrees to floating-point Celsius temperatures with 3 digits of precision. Use the formula
celsius = 5.0 / 9.0 * ( fahrenheit - 32 );
to perform the calculation. The output should be printed in two right-justified columns and the Celsius temperatures should be preceded by a sign for both positive and negative values.

example.code:
#include <iostream>
#include <iomanip>

int main() {
    // 1. Ephemeral setw vs sticky setfill
    std::cout << "--- 1. Ephemeral Width ---\n";
    std::cout << "12345\n";
    std::cout.width(5);
    std::cout.fill('*');
    std::cout << 123 << "\n";
    std::cout << 123 << "\n"; // Width automatically reset to 0; fill remains '*'

    // 2. Base formatting and prefixes
    std::cout << "--- 2. Base Formatting ---\n";
    int val = 99;
    std::cout << std::showbase << std::oct << val << "\n";
    std::cout << std::hex << val << "\n";

    // 3. Showpos and scientific
    std::cout << "--- 3. Signs and Floating-Point ---\n";
    std::cout << std::dec << 100000 << "\n";
    std::cout << std::showpos << 100000 << "\n";
    std::cout << std::setw(10) << std::setprecision(2) << std::scientific << 444.93738 << "\n";

    // 4. Casting char* to void* to demonstrate address inspection intent
    std::cout << "--- 4. String Pointer Casting ---\n";
    const char message[] = "Antigravity";
    std::cout << "As string content: " << message << "\n";
    std::cout << "Cast to void* is non-null: " << (static_cast<const void*>(message) != nullptr) << "\n";

    return 0;
}

#include <iostream>
#include <sstream>

int main() {
    std::istringstream stream("Alpha.Beta Gamma");
    char buffer[20]{};

    // 1. Using get(buf, count, delim): leaves delim in stream
    stream.get(buffer, 10, '.');
    std::cout << "get extracted: " << buffer << "\n";
    std::cout << "Next char in stream (peek): '" << static_cast<char>(stream.peek()) << "'\n";

    // 2. Discard delimiter '.' using ignore
    stream.ignore(1);

    // 3. Using getline(buf, count, delim): extracts and discards delim
    stream.getline(buffer, 10, ' ');
    std::cout << "getline extracted: " << buffer << "\n";
    std::cout << "Next char after getline (peek): '" << static_cast<char>(stream.peek()) << "'\n";

    // 4. Using read and gcount
    char block[10]{};
    stream.read(block, 5);
    std::cout << "Read " << stream.gcount() << " chars: ";
    std::cout.write(block, stream.gcount()) << "\n";

    // 5. Test error flags
    std::cout << "Stream good: " << stream.good() << ", eof: " << stream.eof() << "\n";

    return 0;
}
